-- Bảng: trovio.timeline_events (9 dòng)
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-dgnl-hn-dot-1', 'Thi đánh giá năng lực ĐHQG Hà Nội (HSA) — đợt đầu', '2026-03-13T17:00:00.000Z', '2026-03-14T17:00:00.000Z', 'dgnl', 'Các đợt thi HSA thường bắt đầu từ tháng 3. Đăng ký trên cổng thi của ĐHQG Hà Nội trước ngày thi vài tuần.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-dgnl-hcm-dot-1', 'Thi đánh giá năng lực ĐHQG TP.HCM — đợt 1', '2026-04-04T17:00:00.000Z', NULL, 'dgnl', 'Kỳ thi thang 1200 điểm, thường tổ chức 2 đợt vào tháng 4 và tháng 5–6.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-dang-ky-thi-thpt', 'Đăng ký dự thi tốt nghiệp THPT', '2026-04-20T17:00:00.000Z', '2026-05-04T17:00:00.000Z', 'dang-ky', 'Học sinh lớp 12 đăng ký dự thi qua trường THPT hoặc trực tuyến trên hệ thống của Bộ.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-thi-thpt', 'Kỳ thi tốt nghiệp THPT', '2026-06-24T17:00:00.000Z', '2026-06-25T17:00:00.000Z', 'thi', 'Hai ngày thi chính thức. Mang theo giấy báo dự thi và giấy tờ tuỳ thân.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-cong-bo-diem', 'Công bố điểm thi tốt nghiệp THPT', '2026-07-15T17:00:00.000Z', NULL, 'ket-qua', 'Tra cứu điểm thi, sau đó cập nhật điểm vào Trovio để xem lại mức cạnh tranh tham khảo.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-dang-ky-nguyen-vong', 'Đăng ký & điều chỉnh nguyện vọng xét tuyển', '2026-07-17T17:00:00.000Z', '2026-07-29T17:00:00.000Z', 'dang-ky', 'Đăng ký tối đa 15 nguyện vọng theo Quy chế tuyển sinh 2026 (Thông tư 06/2026/TT-BGDĐT), sắp xếp theo mức độ mong muốn thực tế. Dùng “Kiểm tra danh sách” ở trang Đã lưu trước khi nộp.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-nop-le-phi', 'Nộp lệ phí xét tuyển trực tuyến', '2026-07-30T17:00:00.000Z', '2026-08-05T17:00:00.000Z', 'dang-ky', 'Nộp đúng số lượng nguyện vọng đã đăng ký. Nguyện vọng chưa nộp lệ phí sẽ không được xét.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-ket-qua-dot-1', 'Công bố kết quả trúng tuyển đợt 1', '2026-08-19T17:00:00.000Z', NULL, 'ket-qua', 'Mỗi thí sinh chỉ trúng tuyển 1 nguyện vọng — nguyện vọng có thứ tự ưu tiên cao nhất mà bạn đủ điều kiện.') ON CONFLICT DO NOTHING;
INSERT INTO trovio."timeline_events" ("id", "title", "start_date", "end_date", "category", "description") VALUES ('2026-xac-nhan-nhap-hoc', 'Xác nhận nhập học trực tuyến', '2026-08-20T17:00:00.000Z', '2026-08-29T17:00:00.000Z', 'nhap-hoc', 'Xác nhận nhập học trên hệ thống của Bộ trước hạn, sau đó làm thủ tục theo hướng dẫn của trường.') ON CONFLICT DO NOTHING;

